function averageHeightOfBuildings(buildings) {
  const events = [];
  for (const [start, end, height] of buildings) {
    events.push([start, 1, height]);
    events.push([end, -1, -height]);
  }
  events.sort((a, b) => a[0] - b[0]);

  const street = [];
  let count = 0;
  let total = 0;
  let prev = events[0][0];
  for (const [position, delta, change] of events) {
    if (position > prev && count > 0) {
      const average = Math.floor(total / count);
      const last = street[street.length - 1];
      if (last && last[1] === prev && last[2] === average) {
        last[1] = position;
      } else {
        street.push([prev, position, average]);
      }
    }
    count += delta;
    total += change;
    prev = position;
  }
  return street;
}

