function averageHeightOfBuildings(buildings) {
  // Cut the street at every endpoint and average each elementary piece directly.
  const points = [...new Set(buildings.flatMap(([start, end]) => [start, end]))].sort((a, b) => a - b);
  const pieces = [];
  for (let k = 0; k + 1 < points.length; k++) {
    const a = points[k], b = points[k + 1];
    const covering = buildings.filter(([start, end]) => start <= a && b <= end);
    if (covering.length === 0) continue;
    const sum = covering.reduce((s, building) => s + building[2], 0);
    pieces.push([a, b, Math.floor(sum / covering.length)]);
  }
  // Join neighbouring pieces that touch and share an average.
  const result = [];
  for (const piece of pieces) {
    const tail = result.length ? result[result.length - 1] : null;
    if (tail && tail[1] === piece[0] && tail[2] === piece[2]) tail[1] = piece[1];
    else result.push([...piece]);
  }
  return result;
}

