function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const buildings = [];
  if (size === 'small') {
    const n = int(1, 5);
    for (let i = 0; i < n; i++) {
      const start = int(0, 12);
      buildings.push([start, start + int(1, 6), int(1, 6)]);
    }
    return [buildings];
  }
  const n = int(1500, 2000);
  const wide = rand() < 0.5;
  for (let i = 0; i < n; i++) {
    if (wide) {
      const start = int(0, 99999000);
      buildings.push([start, Math.min(100000000, start + int(1, 2000000)), int(1, 100000)]);
    } else {
      const start = int(0, 3000);
      buildings.push([start, start + int(1, 40), int(1, 5)]);
    }
  }
  return [buildings];
}
